const TEAL = 0x00a6a0, FILL = 0xc4e6e0, RED = 0xf4525a,
      CREAM = 0xfbe3b8, GRAY = 0x999999, SLICE = 0x8fcfc8, BLACK = 0x111111;
const FAR = new THREE.Vector3(1e5, 1e5, 1e5);

// graph (x,y,z) → world
function P(x, y, z) { return new THREE.Vector3(y, z, x); }

/* ── generic helpers ─────────────────────────────────────────────────── */
function triMesh(a, b, c, color, opacity) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array([
    a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z]), 3));
  g.computeVertexNormals();
  return new THREE.Mesh(g, new THREE.MeshBasicMaterial({
    color, transparent: true, opacity, side: THREE.DoubleSide, depthWrite: false
  }));
}
function setTri(mesh, a, b, c) {
  const arr = mesh.geometry.attributes.position.array;
  arr[0] = a.x; arr[1] = a.y; arr[2] = a.z;
  arr[3] = b.x; arr[4] = b.y; arr[5] = b.z;
  arr[6] = c.x; arr[7] = c.y; arr[8] = c.z;
  mesh.geometry.attributes.position.needsUpdate = true;
  mesh.geometry.computeBoundingSphere();
}
function lineFrom(pts, color) {
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color }));
}
function emptyLine(n, color) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(n * 3), 3));
  return new THREE.Line(g, new THREE.LineBasicMaterial({ color }));
}
function setLinePts(line, pts) {
  const arr = line.geometry.attributes.position.array;
  for (let i = 0; i < pts.length; i++) { arr[i * 3] = pts[i].x; arr[i * 3 + 1] = pts[i].y; arr[i * 3 + 2] = pts[i].z; }
  line.geometry.attributes.position.needsUpdate = true;
  line.geometry.computeBoundingSphere();
}
function axis3(dir, len) {
  const g = new THREE.Group();
  const end = dir.clone().multiplyScalar(len);
  g.add(lineFrom([new THREE.Vector3(0, 0, 0), end], BLACK));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.26, 16),
    new THREE.MeshBasicMaterial({ color: BLACK }));
  cone.position.copy(end);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  g.add(cone);
  return g;
}
function dot3(p, color) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.065, 18, 14),
    new THREE.MeshBasicMaterial({ color }));
  m.position.copy(p); return m;
}
/* flat 2D helpers (local XY plane) */
function seg2(x1, y1, x2, y2, w, color, z) {
  const dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy) || 1e-5;
  const m = new THREE.Mesh(new THREE.PlaneGeometry(len, w),
    new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide, depthWrite: false, transparent: true }));
  m.position.set((x1 + x2) / 2, (y1 + y2) / 2, z || 0);
  m.rotation.z = Math.atan2(dy, dx);
  return m;
}
function arrow2(x, y, ang, size, color, z) {
  const s = new THREE.Shape();
  s.moveTo(size, 0); s.lineTo(-size * 0.55, size * 0.45); s.lineTo(-size * 0.55, -size * 0.45); s.closePath();
  const m = new THREE.Mesh(new THREE.ShapeGeometry(s),
    new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide, depthWrite: false, transparent: true }));
  m.position.set(x, y, z || 0); m.rotation.z = ang; return m;
}
function poly2(points, color, opacity, z) {
  const s = new THREE.Shape(points.map(p => new THREE.Vector2(p[0], p[1])));
  const m = new THREE.Mesh(new THREE.ShapeGeometry(s), new THREE.MeshBasicMaterial({
    color, transparent: true, opacity, side: THREE.DoubleSide, depthWrite: false
  }));
  m.position.z = z || 0; return m;
}
function disc2(x, y, r, color, z) {
  const m = new THREE.Mesh(new THREE.CircleGeometry(r, 24),
    new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide, depthWrite: false, transparent: true }));
  m.position.set(x, y, z || 0); return m;
}

