(function buildBlockArrow() {
  const cps = [[-3.45, -2.45], [-3.05, -2.80], [-2.30, -3.00], [-1.30, -3.03],
               [-0.55, -2.85], [-0.20, -2.45], [-0.12, -2.00]]
    .map(p => new THREE.Vector2(p[0], p[1]));
  const pts = new THREE.SplineCurve(cps).getPoints(56);
  const half = 0.22, headHalf = 0.52, headLen = 0.5;
  const left = [], right = [];
  for (let i = 0; i < pts.length; i++) {
    const prev = pts[Math.max(0, i - 1)], next = pts[Math.min(pts.length - 1, i + 1)];
    const t = new THREE.Vector2().subVectors(next, prev).normalize();
    const n = new THREE.Vector2(-t.y, t.x);
    left.push(new THREE.Vector2(pts[i].x + n.x * half, pts[i].y + n.y * half));
    right.push(new THREE.Vector2(pts[i].x - n.x * half, pts[i].y - n.y * half));
  }
  const e = pts[pts.length - 1];
  const te = new THREE.Vector2().subVectors(e, pts[pts.length - 2]).normalize();
  const ne = new THREE.Vector2(-te.y, te.x);
  const outline = left.concat([
    new THREE.Vector2(e.x + ne.x * headHalf, e.y + ne.y * headHalf),
    new THREE.Vector2(e.x + te.x * headLen, e.y + te.y * headLen),
    new THREE.Vector2(e.x - ne.x * headHalf, e.y - ne.y * headHalf)
  ], right.slice().reverse());
  const shape = new THREE.Shape(outline);
  const fill = new THREE.Mesh(new THREE.ShapeGeometry(shape),
    new THREE.MeshBasicMaterial({ color: CREAM, side: THREE.DoubleSide, transparent: true, opacity: 0.95, depthWrite: false }));
  arrowGroup.add(fill);
  const loop = outline.map(p => new THREE.Vector3(p.x, p.y, 0.01));
  loop.push(loop[0].clone());
  arrowGroup.add(lineFrom(loop, GRAY));
})();

