  { title: 'Horizontal slices', view: '3D', slice: 2.4, sweep: false,
    text: 'Raise the slicing plane: cross-sections stay similar triangles whose vertices ride the edges, shrinking to nothing at the apex (0, 0, 4).' }
];
let step = 2;
function goToStep(i) {
  step = (i + steps.length) % steps.length;
  const s = steps[step];
  document.getElementById('stepTitle').textContent = (step + 1) + '. ' + s.title;
  document.getElementById('stepText').textContent = s.text;
  setPanelView(s.view);
  killTween('slice'); tweenTo('slice', sliceC, s.slice, 0.9, setSliceC);
  killTween('strip');
