const faceR     = triMesh(O, A, B, FILL, 0.60);   // base region R
const faceSlant = triMesh(A, B, C, FILL, 0.55);   // z = 4 - 4x - 2y
const faceYZ    = triMesh(O, B, C, FILL, 0.16);   // hidden by default
const faceXZ    = triMesh(O, A, C, FILL, 0.16);   // hidden by default
