const stripTri = triMesh(O, O, O, RED, 0.32);
const stripOut = emptyLine(4, RED);
stripTri.visible = stripOut.visible = false;      // off until the student asks
group3D.add(stripTri, stripOut);

const sliceTri = triMesh(O, O, O, SLICE, 0.30);
const sliceOut = emptyLine(4, TEAL);
sliceTri.visible = sliceOut.visible = false;
group3D.add(sliceTri, sliceOut);

/* ── camera pose first, so the inset can be placed in screen coordinates ─ */
setCameraView({ projection: 'orthographic', axisScreenAngles: POSE, heightFraction: 0.7 });
camera.updateMatrixWorld();
const rr = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 0); // screen right
const uu = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 1); // screen up

/* ── 2D INSET (billboarded flat panel, screen-right of the 3D panel) ──── */
const S2 = 1.3;                                  // inset units per graph unit
const insetRoot = new THREE.Group();
insetRoot.position.copy(rr.clone().multiplyScalar(4.81).add(uu.clone().multiplyScalar(1.495)));
scene.add(insetRoot);

const insetGroup = new THREE.Group();
insetGroup.scale.setScalar(S2);
insetGroup.position.set(-0.91, -1.495, 0);       // puts panel origin on the 3D baseline
insetRoot.add(insetGroup);

insetGroup.add(poly2([[0, 0], [1, 0], [0, 2]], FILL, 0.6, 0.0));        // region R
insetGroup.add(seg2(-0.28, 0, 1.45, 0, 0.025, BLACK, 0.012));           // x axis
insetGroup.add(arrow2(1.52, 0, 0, 0.11, BLACK, 0.012));
insetGroup.add(seg2(0, -0.24, 0, 2.32, 0.025, BLACK, 0.012));           // y axis
insetGroup.add(arrow2(0, 2.40, Math.PI / 2, 0.11, BLACK, 0.012));
insetGroup.add(seg2(0, 2, 1, 0, 0.048, TEAL, 0.02));                    // hypotenuse
insetGroup.add(disc2(0, 2, 0.06, TEAL, 0.03));
insetGroup.add(disc2(1, 0, 0.06, TEAL, 0.03));

const strip2 = new THREE.Mesh(new THREE.PlaneGeometry(0.03, 1),
  new THREE.MeshBasicMaterial({ color: RED, side: THREE.DoubleSide, depthWrite: false, transparent: true }));
insetGroup.add(strip2);
const handle2 = disc2(0, 0, 0.07, RED, 0.05);
insetGroup.add(handle2);

const dragPlane = new THREE.Mesh(new THREE.PlaneGeometry(2.2, 3.0),
  new THREE.MeshBasicMaterial({ visible: false, side: THREE.DoubleSide }));
dragPlane.position.set(0.55, 1.05, 0.01);
insetGroup.add(dragPlane);

/* ── linking block arrow (child of insetRoot → screen-aligned) ────────── */
const arrowGroup = new THREE.Group();
insetRoot.add(arrowGroup);
(function buildBlockArrow() {
  const cps = [[-4.30, -2.05], [-4.02, -2.46], [-3.20, -2.72], [-2.20, -2.80],
               [-1.30, -2.62], [-0.68, -2.44], [-0.45, -2.25]]
    .map(p => new THREE.Vector2(p[0], p[1]));
  const pts = new THREE.SplineCurve(cps).getPoints(64);
  const half = 0.22, headHalf = 0.55, headLen = 0.50;
  const left = [], right = [];
  for (let i = 0; i < pts.length; i++) {
    const prev = pts[Math.max(0, i - 1)], next = pts[Math.min(pts.length - 1, i + 1)];
    const t = new THREE.Vector2().subVectors(next, prev).normalize();
    const n = new THREE.Vector2(-t.y, t.x);
    left.push(new THREE.Vector2(pts[i].x + n.x * half, pts[i].y + n.y * half));
    right.push(new THREE.Vector2(pts[i].x - n.x * half, pts[i].y - n.y * half));
  }
  const e = pts[pts.length - 1];
  const te = new THREE.Vector2().subVectors(e, pts[pts.length - 2]).normalize();
  const ne = new THREE.Vector2(-te.y, te.x);
  const outline = left.concat([
    new THREE.Vector2(e.x + ne.x * headHalf, e.y + ne.y * headHalf),
    new THREE.Vector2(e.x + te.x * headLen, e.y + te.y * headLen),
    new THREE.Vector2(e.x - ne.x * headHalf, e.y - ne.y * headHalf)
  ], right.slice().reverse());
  const shape = new THREE.Shape(outline);
  arrowGroup.add(new THREE.Mesh(new THREE.ShapeGeometry(shape),
    new THREE.MeshBasicMaterial({ color: CREAM, side: THREE.DoubleSide, transparent: true, opacity: 0.95, depthWrite: false })));
  const loop = outline.map(p => new THREE.Vector3(p.x, p.y, 0.01));
  loop.push(loop[0].clone());
  arrowGroup.add(lineFrom(loop, GRAY));
})();

/* ── state + updaters ────────────────────────────────────────────────── */
let stripX = 0.55, sliceC = 0, panelView = 'both', strip3DOn = false;

function refreshStrip3D() {
  const on = strip3DOn && group3D.visible;
  stripTri.visible = on; stripOut.visible = on;
  const cb = document.getElementById('chkStrip3D');
  if (cb) cb.checked = strip3DOn;
}
function setStripX(v) {
  stripX = Math.min(1, Math.max(0, v));
  const h = 2 - 2 * stripX;
  strip2.scale.set(1, Math.max(h, 1e-4), 1);
  strip2.position.set(stripX, h / 2, 0.04);
  handle2.position.set(stripX, h, 0.05);
  const a = P(stripX, 0, 0), b = P(stripX, h, 0), c = P(stripX, 0, 4 - 4 * stripX);
  setTri(stripTri, a, b, c);
  setLinePts(stripOut, [a, b, c, a]);
  const sx = document.getElementById('stripX');
  if (sx && Math.abs(parseFloat(sx.value) - stripX) > 1e-6) sx.value = stripX.toFixed(2);
  document.getElementById('xVal').textContent = stripX.toFixed(2);
  updateReadout();
}
function setSliceC(v) {
  sliceC = Math.min(4, Math.max(0, v));
  const lx = (4 - sliceC) / 4, ly = (4 - sliceC) / 2;
  const a = P(0, 0, sliceC), b = P(lx, 0, sliceC), c = P(0, ly, sliceC);
  setTri(sliceTri, a, b, c);
  setLinePts(sliceOut, [a, b, c, a]);
  const on = sliceC > 0.02 && group3D.visible;
  sliceTri.visible = on; sliceOut.visible = on;
  const sl = document.getElementById('sliceHeight');
  if (sl && Math.abs(parseFloat(sl.value) - sliceC) > 1e-6) sl.value = sliceC.toFixed(2);
  document.getElementById('cVal').textContent = sliceC.toFixed(2);
  updateReadout();
}
function updateReadout() {
  const h = 2 - 2 * stripX, area = h * h;
  const sA = Math.pow(4 - sliceC, 2) / 16;
  document.getElementById('readout').innerHTML =
    'inner limits: 0 ≤ <i>y</i> ≤ 2 − 2<i>x</i> = ' + h.toFixed(2) + '<br>' +
    'strip area ∫<sub>0</sub><sup>2−2x</sup>(4−4<i>x</i>−2<i>y</i>)d<i>y</i> = (2−2<i>x</i>)² = ' + area.toFixed(3) + '<br>' +
    'slice at <i>z</i>=<i>c</i>: legs ' + ((4 - sliceC) / 4).toFixed(2) + ' × ' + ((4 - sliceC) / 2).toFixed(2) +
    ', area = ' + sA.toFixed(3) + '<br>' +
    'volume = ∫<sub>0</sub><sup>1</sup>(2−2<i>x</i>)²d<i>x</i> = 4/3 ≈ 1.333';
}

/* ── camera framing ──────────────────────────────────────────────────── */
function updateBillboards() { insetRoot.quaternion.copy(camera.quaternion); }

function frame(objs, hf) {
  const base = {
    projection: 'orthographic', axisScreenAngles: POSE, heightFraction: hf
  };
  setCameraView(base);
  updateBillboards();
  const box = new THREE.Box3();
  objs.forEach(o => { o.updateWorldMatrix(true, true); box.expandByObject(o); });
  if (box.isEmpty()) return;
  const ctr = box.getCenter(new THREE.Vector3());
  camera.updateMatrixWorld();
  const tv = camera.matrixWorldInverse, p = new THREE.Vector3();
  let mnx = Infinity, mxx = -Infinity, mny = Infinity, mxy = -Infinity;
  for (let i = 0; i < 8; i++) {
    p.set(i & 1 ? box.max.x : box.min.x, i & 2 ? box.max.y : box.min.y, i & 4 ? box.max.z : box.min.z)
      .applyMatrix4(tv);
    mnx = Math.min(mnx, p.x); mxx = Math.max(mxx, p.x);
    mny = Math.min(mny, p.y); mxy = Math.max(mxy, p.y);
  }
  const H = Math.max(mxy - mny, 1e-6), W = Math.max(mxx - mnx, 1e-6);
  const z = Math.min(Math.max(Math.min((2 * d * hf) / H, (2 * d * aspect * hf) / W), 0.2), 5);
  setCameraView(Object.assign({}, base, { target: [ctr.x, ctr.y, ctr.z], zoom: z }));
  updateBillboards();
}

function setPanelView(mode) {
  panelView = mode;
  group3D.visible = mode !== '2D';
  insetRoot.visible = mode !== '3D';
  insetGroup.visible = mode !== '3D';
  arrowGroup.visible = mode === 'both';
  refreshStrip3D();
  setSliceC(sliceC);
  document.getElementById('btnView3D').classList.toggle('active', mode === '3D');
  document.getElementById('btnView2D').classList.toggle('active', mode === '2D');
  document.getElementById('btnViewBoth').classList.toggle('active', mode === 'both');
  if (mode === 'both') frame([group3D, insetGroup, arrowGroup], 0.86);
  else if (mode === '3D') frame([group3D], 0.8);
  else frame([insetGroup], 0.82);
}

/* ── initial state ───────────────────────────────────────────────────── */
setStripX(0.55);
setSliceC(0);
updateBillboards();

/* ── labels ──────────────────────────────────────────────────────────── */
const dynLabels = [];
function addDyn(text, getPos, opts, vis) {
  const e = addLabel(text, new THREE.Vector3(), opts || {});
  dynLabels.push({ e: e, getPos: getPos, vis: vis });
  return e;
}
const SER = "font-family:Georgia,'Times New Roman',serif;";
const M = t => '<span style="' + SER + '">' + t + '</span>';
const L3 = () => group3D.visible;
const L2 = () => insetGroup.visible;
const F = (x, y, z) => () => P(x, y, z);
const FI = (x, y) => () => insetGroup.localToWorld(new THREE.Vector3(x, y, 0.06));

addDyn(M('<i>z</i>'), F(0, 0, 4.95), { fontSize: '18px', offset: [13, -2] }, L3);
addDyn(M('<i>y</i>'), F(0, 2.95, 0), { fontSize: '18px', offset: [2, -17] }, L3);
addDyn(M('<i>x</i>'), F(1.75, 0, 0), { fontSize: '18px', offset: [-12, 14] }, L3);
addDyn(M('4'), F(0, 0, 4), { fontSize: '17px', offset: [-19, -1] }, L3);
addDyn(M('2'), F(0, 2, 0), { fontSize: '17px', offset: [-1, -19] }, L3);
addDyn(M('1'), F(1, 0, 0), { fontSize: '17px', offset: [-21, -5] }, L3);
addDyn(M('<i>R</i>'), F(0.30, 0.52, 0), { fontSize: '17px', offset: [6, -5] }, L3);
addDyn(M('<i>z</i> = 4 − 4<i>x</i> − 2<i>y</i>'), F(0.15, 1.5, 2.0), { fontSize: '17px', offset: [34, 0] }, L3);

addDyn(M('<i>x</i>'), FI(1.60, 0.20), { fontSize: '18px' }, L2);
addDyn(M('<i>y</i>'), FI(0.16, 2.52), { fontSize: '18px' }, L2);
addDyn(M('0'), FI(-0.17, -0.22), { fontSize: '17px' }, L2);
addDyn(M('2'), FI(-0.20, 2.0), { fontSize: '17px' }, L2);
addDyn(M('1'), FI(1.0, -0.24), { fontSize: '17px' }, L2);
addDyn(M('<i>R</i>'), FI(0.20, 0.72), { fontSize: '17px' }, L2);
addDyn(M('<i>y</i> = 2 − 2<i>x</i>'), FI(0.98, 1.42), { fontSize: '17px', offset: [32, -2] }, L2);

/* ── hover / click explanations ──────────────────────────────────────── */
registerInteractive(faceSlant, {
  title: 'The plane z = 4 − 4x − 2y',
  tooltip: 'Top surface of the solid',
  body: 'This slanted face is the graph of z = 4 − 4x − 2y. It meets the axes at x = 1, y = 2 and z = 4. Its height above a point (x, y) of R is exactly the integrand of the double integral.'
});
registerInteractive(faceR, {
  title: 'Base region R',
  tooltip: 'R: 0 ≤ x ≤ 1, 0 ≤ y ≤ 2 − 2x',
  body: 'R is the shadow of the tetrahedron in the xy-plane: the triangle with vertices (0,0), (1,0), (0,2), bounded above by y = 2 − 2x (set z = 0 in the plane equation).'
});
registerInteractive(sliceTri, {
  title: 'Horizontal cross-section z = c',
  tooltip: 'Similar triangle at height c',
  body: 'At height c the cross-section is a triangle with legs (4 − c)/4 and (4 − c)/2, area (4 − c)²/16. Integrating it from c = 0 to 4 also gives 4/3.'
});
registerInteractive(stripTri, {
  title: 'Vertical slice at fixed x',
  tooltip: 'Inner integral in y',
  body: 'For fixed x this triangle has area ∫₀^{2−2x}(4 − 4x − 2y) dy = (2 − 2x)². Integrating over x from 0 to 1 gives the volume 4/3.'
});

/* ── tweens + own update loop ────────────────────────────────────────── */
const tweens = {};
function tweenTo(key, from, to, dur, set) { tweens[key] = { from: from, to: to, t: 0, dur: dur, set: set }; }
function killTween(key) { delete tweens[key]; }

let _last = performance.now();
(function tick() {
  requestAnimationFrame(tick);
  const now = performance.now(), dt = Math.min(0.05, (now - _last) / 1000); _last = now;
  for (const k in tweens) {
    const tw = tweens[k];
    tw.t += dt / tw.dur;
    const u = Math.min(1, tw.t), s = u * u * (3 - 2 * u);
    tw.set(tw.from + (tw.to - tw.from) * s);
    if (u >= 1) delete tweens[k];
