  updateBillboards();
  for (const L of dynLabels) L.e.pos.copy(L.vis() ? L.getPos() : FAR);
})();

/* ── controls wiring ─────────────────────────────────────────────────── */
document.getElementById('btnReset').style.display = '';
document.getElementById('btnView3D').addEventListener('click', () => setPanelView('3D'));
document.getElementById('btnView2D').addEventListener('click', () => setPanelView('2D'));
document.getElementById('btnViewBoth').addEventListener('click', () => setPanelView('both'));
document.getElementById('sliceHeight').addEventListener('input', e => { killTween('slice'); setSliceC(parseFloat(e.target.value)); });
document.getElementById('stripX').addEventListener('input', e => {
  killTween('strip'); strip3DOn = true; refreshStrip3D(); setStripX(parseFloat(e.target.value));
