document.getElementById('chkStrip3D').addEventListener('change', e => { strip3DOn = e.target.checked; refreshStrip3D(); });
document.getElementById('chkFaces').addEventListener('change', e => {
  faceYZ.visible = faceXZ.visible = e.target.checked;
});

/* drag the red strip inside the 2D region */
const _rc = new THREE.Raycaster(), _pt = new THREE.Vector2();
let dragging = false;
function rayInset(ev) {
  const r = canvas.getBoundingClientRect();
  _pt.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  _pt.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  _rc.setFromCamera(_pt, camera);
  const hit = _rc.intersectObject(dragPlane, false)[0];
  if (!hit) return null;
  return insetGroup.worldToLocal(hit.point.clone());
}
function insideR(p) {
  const nearHandle = Math.abs(p.x - stripX) < 0.16 && p.y > -0.15 && p.y < 2.15;
  return nearHandle || (p.x >= -0.06 && p.x <= 1.06 && p.y >= -0.14 && p.y <= 2 - 2 * p.x + 0.14);
}
canvas.addEventListener('pointerdown', ev => {
  if (!insetGroup.visible) return;
  const loc = rayInset(ev);
  if (!loc || !insideR(loc)) return;
  dragging = true; controls.enabled = false; killTween('strip');
  strip3DOn = true; refreshStrip3D();
  setStripX(loc.x);
}, true);
canvas.addEventListener('pointermove', ev => {
  if (!dragging) return;
  const loc = rayInset(ev);
  if (loc) setStripX(loc.x);
});
window.addEventListener('pointerup', () => { if (dragging) { dragging = false; controls.enabled = true; } });

/* ── guided demo ─────────────────────────────────────────────────────── */
const steps = [
  { title: 'The base region R', view: '2D', slice: 0, sweep: false,
    text: 'Start in the xy-plane: R is the right triangle with legs on the axes, capped by the line y = 2 − 2x (set z = 0 in the plane equation).' },
  { title: 'Inner integral: sweep in y', view: '2D', slice: 0, sweep: true,
    text: 'Drag the red strip. At each fixed x it runs from y = 0 up to y = 2 − 2x — the inner limits of integration.' },
  { title: 'Lift into 3D', view: 'both', slice: 0, sweep: false,
    text: 'The same triangle is the base of the tetrahedron; above each point of R the solid rises to the plane z = 4 − 4x − 2y, the integrand.' },
  { title: 'Horizontal slices', view: '3D', slice: 2.4, sweep: false,
