document.getElementById('btnNext').addEventListener('click', () => goToStep(step + 1));

document.getElementById('stepTitle').textContent = '3. ' + steps[2].title;
document.getElementById('stepText').textContent = steps[2].text;
setPanelView('both');
// @FIGURE_CODE_END

