  ─────────────────────────────────────────────────────────────────────── */

const TEAL = 0x00a6a0, FILL = 0xc4e6e0, RED = 0xf4525a,
      CREAM = 0xfbe3b8, GRAY = 0x999999, SLICE = 0x8fcfc8, BLACK = 0x111111;
const FAR = new THREE.Vector3(1e5, 1e5, 1e5);
const POSE = { x: 7, z: 50 };                 // measured off the source figure

function P(x, y, z) { return new THREE.Vector3(y, z, x); }   // graph → world

/* ── helpers ─────────────────────────────────────────────────────────── */
function triMesh(a, b, c, color, opacity) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array([
    a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z]), 3));
