/* ── camera framing ──────────────────────────────────────────────────── */
function updateBillboards() { insetRoot.quaternion.copy(camera.quaternion); }

function frame(objs, hf) {
  const base = {
    projection: 'orthographic', axisScreenAngles: POSE, heightFraction: hf
  };
  setCameraView(base);
  updateBillboards();
  const box = new THREE.Box3();
  objs.forEach(o => { o.updateWorldMatrix(true, true); box.expandByObject(o); });
  if (box.isEmpty()) return;
  const ctr = box.getCenter(new THREE.Vector3());
  camera.updateMatrixWorld();
  const tv = camera.matrixWorldInverse, p = new THREE.Vector3();
  let mnx = Infinity, mxx = -Infinity, mny = Infinity, mxy = -Infinity;
  for (let i = 0; i < 8; i++) {
    p.set(i & 1 ? box.max.x : box.min.x, i & 2 ? box.max.y : box.min.y, i & 4 ? box.max.z : box.min.z)
      .applyMatrix4(tv);
    mnx = Math.min(mnx, p.x); mxx = Math.max(mxx, p.x);
    mny = Math.min(mny, p.y); mxy = Math.max(mxy, p.y);
  }
  const H = Math.max(mxy - mny, 1e-6), W = Math.max(mxx - mnx, 1e-6);
  const z = Math.min(Math.max(Math.min((2 * d * hf) / H, (2 * d * aspect * hf) / W), 0.2), 5);
  setCameraView(Object.assign({}, base, { target: [ctr.x, ctr.y, ctr.z], zoom: z }));
  updateBillboards();
}

function setPanelView(mode) {
  panelView = mode;
  group3D.visible = mode !== '2D';
  insetRoot.visible = mode !== '3D';
  insetGroup.visible = mode !== '3D';
  arrowGroup.visible = mode === 'both';
  if (mode === '3D') handle2.visible = false;
  refreshStrip3D();
  setSliceC(sliceC);
  document.getElementById('btnView3D').classList.toggle('active', mode === '3D');
  document.getElementById('btnView2D').classList.toggle('active', mode === '2D');
  document.getElementById('btnViewBoth').classList.toggle('active', mode === 'both');
  if (mode === 'both') frame([group3D, insetGroup, arrowGroup], 0.88);
  else if (mode === '3D') frame([group3D], 0.8);
  else frame([insetGroup], 0.82);
}

